#include <vector>
#include <algorithm>

class Solution {
public:
    int timeRequiredToBuy(std::vector<int>& tickets, int k) {
        int target = tickets[k];
        int time = 0;
        for (int i = 0; i < static_cast<int>(tickets.size()); ++i) {
            if (i <= k) time += std::min(tickets[i], target);
            else time += std::min(tickets[i], target - 1);
        }
        return time;
    }
};

class Solution {
    public int timeRequiredToBuy(int[] tickets, int k) {
        int target = tickets[k];
        int time = 0;
        for (int i = 0; i < tickets.length; i++) {
            if (i <= k) time += Math.min(tickets[i], target);
            else time += Math.min(tickets[i], target - 1);
        }
        return time;
    }
}

